import{_ as s,o as n,c as o,a2 as i}from"./chunks/framework.Zh78JZbW.js";const c=JSON.parse('{"title":"Ton skin","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skin.md","filePath":"guide/skin.md"}'),r={name:"guide/skin.md"};function t(a,e,l,u,d,m){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="ton-skin" tabindex="-1">Ton skin <a class="header-anchor" href="#ton-skin" aria-label="Permalink to &quot;Ton skin&quot;">​</a></h1><p>Ton skin se règle dans les <strong>Paramètres</strong> (l&#39;engrenage), et tous les joueurs Kodus le voient en jeu.</p><ol><li>Trouve un skin : un fichier PNG de 64×64 pixels (ou 64×32). Des sites comme NameMC ou The Skindex en proposent des milliers, ou fais le tien.</li><li>Paramètres → <strong>Choisir un fichier PNG…</strong>. L&#39;aperçu 3D te montre le résultat.</li><li>Choisis le modèle : <strong>Classique</strong> (bras larges, comme Steve) ou <strong>Fin</strong> (bras fins, comme Alex). Si les bras ont une bande vide, change de modèle.</li><li>Clique <strong>Appliquer</strong>.</li></ol><h2 id="a-savoir" tabindex="-1">À savoir <a class="header-anchor" href="#a-savoir" aria-label="Permalink to &quot;À savoir&quot;">​</a></h2><ul><li><strong>Ton pseudo t&#39;appartient</strong> dès ton premier skin envoyé : personne d&#39;autre ne peut mettre un skin avec ce pseudo. Si tu changes de PC, demande à l&#39;admin de libérer ton pseudo.</li><li><strong>Le skin se voit dans les instances avec un loader</strong> (Fabric, Quilt, Forge, NeoForge) : Kodus y installe tout seul le mod CustomSkinLoader. En Vanilla, pas de skin.</li><li>Les autres doivent aussi jouer avec Kodus (ou avoir CustomSkinLoader réglé sur notre serveur) pour voir ton skin.</li><li>Un nouveau skin peut mettre une minute à apparaître en jeu.</li></ul>',5)])])}const g=s(r,[["render",t]]);export{c as __pageData,g as default};
